const requete = $('Demander les resultats').first().json;
const demande = String((requete.query && requete.query.campagneId) || '').trim();

const campagnes = ($('Agreger les campagnes').first().json.campagnes || [])
  .filter(c => c && c['Campagne ID']);
const resultats = ($input.first().json.resultats || [])
  .filter(r => r && r['Campagne ID']);

function nombreOuNull(v) {
  if (v === '' || v == null) return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
}

// La ventilation du cout est stockee en JSON avec la campagne, tarif compris.
// On la relit telle quelle : une campagne ancienne garde le prix qui
// s appliquait le jour ou elle a tourne, meme si la grille a change depuis.
function lireCout(c) {
  try {
    const o = JSON.parse(c['Cout detail'] || '{}');
    if (o && typeof o.total === 'number') return o;
  } catch (e) {}
  const total = nombreOuNull(c['Cout USD']);
  return total === null ? null : { total, estime: true };
}

function resumerCampagne(c) {
  return {
    campagneId: c['Campagne ID'],
    date: c['Date'] || '',
    nom: c['Nom'] || '',
    mode: c['Mode'] || '',
    temperature: nombreOuNull(c['Temperature']),
    repetitions: Number(c['Repetitions']) || 0,
    nbCas: Number(c['Nb cas']) || 0,
    nbAppels: Number(c['Nb appels']) || 0,
    statut: c['Statut'] || '',
    tauxReussite: nombreOuNull(c['Taux reussite']),
    casInstables: nombreOuNull(c['Cas instables']),
    scoreMoyen: nombreOuNull(c['Score moyen']),
    tokensEntree: nombreOuNull(c['Tokens entree']),
    tokensSortie: nombreOuNull(c['Tokens sortie']),
    cout: lireCout(c)
  };
}

if (!demande) {
  // Plus recente d abord, triee par date : l ordre des lignes du Sheet n est pas fiable
  // (des lignes supprimees a la main laissent des trous ou l append s insere).
  const liste = campagnes.map(resumerCampagne).sort((a, b) => String(b.date).localeCompare(String(a.date)));
  return [{ json: { type: 'liste', campagnes: liste } }];
}

const brute = campagnes.filter(c => c['Campagne ID'] === demande).pop();

if (!brute) {
  return [{ json: { type: 'introuvable', campagneId: demande, erreur: 'No campaign with this id.' } }];
}

const campagne = resumerCampagne(brute);
campagne.prompt = brute['Prompt'] || '';
campagne.diagnostic = brute['Diagnostic'] || '';
campagne.promptCorrige = brute['Prompt corrige'] || '';

let analyse = { problemes: [], changements: [], confiance: '' };
try {
  const a = JSON.parse(brute['Analyse'] || '{}');
  analyse = {
    problemes: Array.isArray(a.problemes) ? a.problemes : [],
    changements: Array.isArray(a.changements) ? a.changements : [],
    confiance: a.confiance || ''
  };
} catch (e) {}
campagne.problemes = analyse.problemes;
campagne.changements = analyse.changements;
campagne.confianceAnalyse = analyse.confiance;

const lignes = resultats.filter(r => r['Campagne ID'] === demande);

// --- Gestion des erreurs -------------------------------------------------
// Le workflow d erreur passe la campagne en "erreur" quand le moteur plante.
// Filet de securite : si le serveur lui-meme tombe (memoire, redemarrage),
// aucun workflow d erreur ne tourne. Une campagne encore "en cours" au-dela
// du timeout du moteur (30 min) est alors declaree en erreur ici.
const TIMEOUT_MS = 35 * 60 * 1000;
if (campagne.statut === 'erreur') {
  return [{ json: { type: 'erreur', campagne, erreur: campagne.diagnostic || 'The run stopped on an error.', cas: [], detail: [] } }];
}
if (campagne.statut !== 'termine') {
  const debut = Date.parse(campagne.date);
  if (!isNaN(debut) && Date.now() - debut > TIMEOUT_MS) {
    return [{ json: { type: 'erreur', campagne, erreur: 'The run did not finish within 35 minutes: the server stopped before the end. Launch it again.', cas: [], detail: [] } }];
  }
  return [{ json: { type: 'en cours', campagne, cas: [], detail: [] } }];
}

if (lignes.length === 0) {
  campagne.resultatsManquants = true;
  return [{ json: { type: 'campagne', campagne, cas: [], detail: [] } }];
}

const prixIn = campagne.cout && typeof campagne.cout.prixIn === 'number' ? campagne.cout.prixIn : 0;
const prixOut = campagne.cout && typeof campagne.cout.prixOut === 'number' ? campagne.cout.prixOut : 0;
const usd = (tin, tout) => Math.round(((tin * prixIn + tout * prixOut) / 1e6) * 1e6) / 1e6;

const parCas = {};
lignes.forEach(l => {
  const id = l['Cas ID'];
  if (!parCas[id]) {
    parCas[id] = { casId: id, entree: l['Entree'] || '', attendu: l['Attendu'] || '', sorties: [], scores: [], reussites: 0, total: 0, tIn: 0, tOut: 0 };
  }
  const c = parCas[id];
  c.total += 1;
  if (String(l['Reussi']).toLowerCase() === 'oui') c.reussites += 1;
  c.sorties.push(String(l['Sortie'] == null ? '' : l['Sortie']));
  const s = nombreOuNull(l['Score']);
  if (s !== null) c.scores.push(s);
  c.tIn += nombreOuNull(l['Tokens entree']) || 0;
  c.tOut += nombreOuNull(l['Tokens sortie']) || 0;
});

const cas = Object.values(parCas).map(c => {
  // Deduplication insensible a la casse, mais on renvoie le texte tel qu il a ete produit.
  const vues = {};
  const distinctes = [];
  c.sorties.forEach(s => {
    const cle = s.toLowerCase().trim();
    if (!vues[cle]) { vues[cle] = true; distinctes.push(s.trim()); }
  });
  let statut = 'echec';
  if (c.reussites === c.total) statut = 'reussi';
  else if (c.reussites > 0) statut = 'instable';
  return {
    casId: c.casId,
    entree: c.entree,
    attendu: c.attendu,
    reussites: c.reussites,
    total: c.total,
    statut,
    stable: distinctes.length === 1,
    sortiesDistinctes: distinctes,
    exemple: (c.sorties[0] || '').trim(),
    scores: c.scores,
    scoreMoyen: c.scores.length ? Math.round(c.scores.reduce((a, b) => a + b, 0) / c.scores.length * 10) / 10 : null,
    scoreMin: c.scores.length ? Math.min.apply(null, c.scores) : null,
    scoreMax: c.scores.length ? Math.max.apply(null, c.scores) : null,
    tokensIn: c.tIn,
    tokensOut: c.tOut,
    cout: c.tIn || c.tOut ? usd(c.tIn, c.tOut) : null
  };
}).sort((a, b) => a.casId.localeCompare(b.casId, undefined, { numeric: true }));

const detail = lignes.map(l => ({
  casId: l['Cas ID'],
  repetition: Number(l['Repetition']) || 0,
  sortie: l['Sortie'] || '',
  reussi: String(l['Reussi']).toLowerCase() === 'oui',
  score: nombreOuNull(l['Score']),
  justification: l['Justification'] || '',
  erreur: l['Erreur'] || '',
  tokensIn: nombreOuNull(l['Tokens entree']),
  tokensOut: nombreOuNull(l['Tokens sortie'])
}));

return [{ json: { type: 'campagne', campagne, cas, detail } }];
